package com.booksyde.service; import com.booksyde.dto.response.SellerResponse; import com.booksyde.exception.ResourceNotFoundException; import com.booksyde.repository.MarketplaceSellerRepository; import java.util.UUID; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class SellerService{private final MarketplaceSellerRepository repo; public SellerService(MarketplaceSellerRepository r){repo=r;} @Transactional(readOnly=true) public SellerResponse get(UUID id){var s=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Vendedor não encontrado."));return new SellerResponse(id,s.isSandboxReady(),s.isLiveReady(),s.isFeatured());}}
